package com.dynokore.platform.serviceruntime.persistence

import com.dynokore.platform.serviceruntime.persistence.jooq.tables.references.ACCOUNT
import com.dynokore.platform.serviceruntime.persistence.jooq.tables.references.LEDGER_ENTRY
import io.kotest.matchers.nulls.shouldBeNull
import io.kotest.matchers.shouldBe
import org.junit.jupiter.api.Test
import java.nio.file.Files
import java.nio.file.Path

/**
 * INV-T-4224 (ruling INV-Q-6546): the persistence tests' records are generated by gst.jooq-codegen, not written by
 * hand.
 */
class GeneratedRecordsTest {
    @Test
    fun `the generated versioned table has recordVersion named version and the unversioned one has none`() {
        ACCOUNT.recordVersion.name shouldBe "version"
        LEDGER_ENTRY.recordVersion.shouldBeNull()
    }

    @Test
    fun `no persistence test holds a hand-written table or record class`() {
        val directory = Path.of("src/implTest/kotlin/com/dynokore/platform/serviceruntime/persistence")
        // assembled, so that this file is not itself what the git grep of the task finds
        val handWritten = listOf("Updatable" + "RecordImpl", "Table" + "RecordImpl", "Table" + "Impl")
        val offenders =
            Files.walk(directory).use { paths ->
                paths
                    .filter { it.toString().endsWith(".kt") && it.fileName.toString() != "GeneratedRecordsTest.kt" }
                    .filter { file -> Files.readString(file).let { text -> handWritten.any { it in text } } }
                    .map { it.toString() }
                    .toList()
            }
        offenders shouldBe emptyList()
    }
}
